'use strict';
/* public/js/76-console.js -- ENV hazard registry + the developer console and its commands. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- environmental hazards: one registry for everything that can be spawned on demand ---------- */
/* ENV.<kind>.spawn({x,z,a}) builds the hazard at x,z heading a (radians). spawnEnv() is the one way to create one:
   the host's console calls it with share=true and the server relays it to every camper, who call spawnEnv() with
   the same numbers, so everyone gets the same hazard. To add a new hazard: add an ENV entry and a console command. */
const ENV={
  twister:{spawn:o=>addTwister(o.x,o.z,o.a)},
  // seed comes from x/z alone (not the clock), so every client hashes the exact same seed from the exact same
  // shared numbers -- only t0 (each client's own twNow() at the moment it hears about it) can drift a little.
  landslide:{spawn:o=>spawnLandslide(o.x,o.z,(hash2(Math.round(o.x*10),Math.round(o.z*10))*4294967296)>>>0,twNow())},
  haboob:{spawn:o=>addHaboob(o.a,o.x,o.z)},   // o.a: compass bearing it comes from; o.x/o.z: the host's spot when they typed it (see 75-haboob.js)
};
function spawnEnv(k,o,by){
  if(!ENV[k])return false;
  ENV[k].spawn(o);
  if(by&&S.started)toast(`${by} spawned a ${k}.`,'',2500);
  return true;
}
/* spawn a hazard `dist` m in front of the camera, heading straight at you; shared with everyone when online */
function spawnAhead(k,dist){
  const a=P.yaw+Math.PI,x=clamp(P.x+Math.sin(a)*dist,-EDGE+10,EDGE-10),z=clamp(P.z+Math.cos(a)*dist,-EDGE+10,EDGE-10);
  const o={x,z,a:Math.atan2(P.z-z,P.x-x)};
  spawnEnv(k,o);if(online())wsSend({t:'env',k,...o});
  return o;
}

/* ---------- developer console ---------- */
/* Open with the ` key (next to 1), or the >_ button on touch screens. Commands are case-insensitive.
   Who can use it: the host (always host on the play-test server, which runs with DEV_MODE=1), or anyone playing solo
   offline. Friends on the real server can't.
   To add a command:  command('name', {usage:'name <arg>', help:'what it does', run(args){ ...; return 'reply' }});
   run() gets the words after the command name. Return a string to print it; throw an Error to print it in red. */
const conEl=$('#console'),conLog=$('#conLog'),conIn=$('#conIn');
const CMDS=new Map(),conHist=[];let conHi=0;
function command(name,def){CMDS.set(name,def)}
function canConsole(){return!online()||net.host}
function conPrint(text,cls){const d=document.createElement('div');if(cls)d.className=cls;d.textContent=text;conLog.appendChild(d);while(conLog.children.length>60)conLog.firstChild.remove();conLog.scrollTop=1e9}
function openConsole(){
  if(!canConsole()){toast('The console is only for the host.','bad',2000);return}
  conEl.hidden=false;releaseLock();digHeld=false;for(const k in KEYS)KEYS[k]=false;
  if(!conLog.children.length)conPrint('Camp Green Lake console. Type help for commands.');
  conIn.value='';conIn.focus();   // focus right away, so fast typing never leaks keys into the game
}
function closeConsole(){conEl.hidden=true;conIn.blur()}
function consoleOpen(){return!conEl.hidden}
function runCommand(line){
  const words=line.trim().split(/\s+/).filter(Boolean);if(!words.length)return;
  const name=words[0].toLowerCase(),c=CMDS.get(name);
  conPrint('> '+line.trim(),'cmd');
  if(!c){conPrint(`Unknown command "${name}". Type help.`,'err');logEv('cmd',{line,error:`Unknown command "${name}"`});return}
  if(!S.started&&c.needsGame!==false){conPrint('Start the game first.','err');logEv('cmd',{line,error:'Start the game first.'});return}
  try{const out=c.run(words.slice(1));if(out)conPrint(String(out),'ok');logEv('cmd',{line,reply:out?String(out).slice(0,300):''})}catch(err){conPrint(err.message,'err');logEv('cmd',{line,error:String(err.message||err).slice(0,300)})}
}
function conKey(e){
  if(e.key==='Escape'||e.key==='`'){e.preventDefault();closeConsole();return}
  if(e.key==='Enter'){e.preventDefault();const v=conIn.value;conIn.value='';if(v.trim()){conHist.push(v);conHi=conHist.length}runCommand(v);return}
  if(e.key==='ArrowUp'){e.preventDefault();if(conHi>0)conIn.value=conHist[--conHi];return}
  if(e.key==='ArrowDown'){e.preventDefault();conHi=Math.min(conHist.length,conHi+1);conIn.value=conHist[conHi]||'';return}
  if(e.key==='Tab'){e.preventDefault();const w=conIn.value.trim().toLowerCase();const m=[...CMDS.keys()].filter(k=>k.startsWith(w));if(m.length===1)conIn.value=m[0]+' ';else if(m.length)conPrint(m.join('  '))}
}
$('#conBtn').onclick=()=>consoleOpen()?closeConsole():openConsole();
const numArg=(v,def,a,b)=>{if(v===undefined)return def;const n=Number(v);if(!Number.isFinite(n))throw new Error(`"${v}" isn't a number.`);return clamp(n,a,b)};

command('help',{needsGame:false,usage:'help',help:'List every command.',run(){return[...CMDS.values()].map(c=>c.usage.padEnd(22)+c.help).join('\n')}});
command('clear',{needsGame:false,usage:'clear',help:'Clear the console.',run(){conLog.textContent=''}});
command('twister',{usage:'twister [distance]',help:'Spawn a twister [45] m in front of you, heading your way. Everyone sees it.',
  run([d]){const dist=numArg(d,45,10,200);spawnAhead('twister',dist);return`Twister spawned ${dist} m ahead.${campDist(P.x,P.z)<50?' (Twisters fall apart near camp; walk out onto the lake to see it at full strength.)':''}`}});
command('landslide',{usage:'landslide [distance]',help:'Trigger a rockslide off Big Thumb, [50] m out from you. Everyone sees it.',
  run([d]){const dist=numArg(d,50,15,200);spawnAhead('landslide',dist);return`Landslide triggered ${dist} m out.`}});
const HB_BRG={n:0,ne:Math.PI/4,e:Math.PI/2,se:Math.PI*3/4,s:Math.PI,sw:Math.PI*5/4,w:Math.PI*3/2,nw:Math.PI*7/4};
command('haboob',{usage:'haboob [direction]',help:'Start a dust storm blowing in from a compass direction (n/ne/e/se/s/sw/w/nw), or a random one. Everyone sees it.',
  run([d]){const k=(d||'').toLowerCase();if(k&&!(k in HB_BRG))throw new Error('Direction must be one of n, ne, e, se, s, sw, w, nw.');
    const a=k?HB_BRG[k]:Math.random()*Math.PI*2,o={x:P.x,z:P.z,a};   // spawn point = wherever the host is standing right now
    spawnEnv('haboob',o);if(online())wsSend({t:'env',k:'haboob',...o});
    return`Dust storm rolling in from the ${compass(Math.sin(a)*100,-Math.cos(a)*100)}.`}});   // same fromVec math as hbCalc's warning toast in 75-haboob.js
command('heal',{usage:'heal',help:'Full health and water.',run(){S.hp=HP_MAX;S.water=waterMax();return'Healed.'}});
command('hurt',{usage:'hurt [amount]',help:'Take [20] damage (to test health and healing).',run([n]){const v=numArg(n,20,1,100);hurt(v,'Hurt','You hurt yourself from the console.');return`-${v} health.`}});
command('tp',{usage:'tp <x> <z> | tp camp',help:'Teleport. The map runs from -595 to 595.',
  run([a,b]){if(a==='camp'){P.x=0;P.z=39}else{if(b===undefined)throw new Error('Usage: tp <x> <z>  or  tp camp');P.x=numArg(a,0,-EDGE+3,EDGE-3);P.z=numArg(b,0,-EDGE+3,EDGE-3)}P.y=groundAt(P.x,P.z);P.vy=P.kx=P.kz=0;return`Teleported to ${P.x.toFixed(0)}, ${P.z.toFixed(0)}.`}});
command('time',{usage:'time <hh:mm>',help:'Set the camp clock for everyone (e.g. time 13:00, time 21:30).',
  run([t]){const m=/^(\d{1,2})(?::(\d{2}))?$/.exec(t||'');if(!m)throw new Error('Usage: time <hh:mm>, e.g. time 13:00');const h=+m[1]+(+m[2]||0)/60;if(h>=24)throw new Error('Hours go 0-23.');jumpTo(tAtHour(h));return`Clock set to ${clockText()}.`}});
command('where',{usage:'where',help:'Print your position.',run(){return`x ${P.x.toFixed(1)}  z ${P.z.toFixed(1)}  (camp is around 0, 39)`}});
command('tent',{usage:'tent <A|B|D|C|out>',help:'Teleport straight into (or out of) a tent, for testing.',
  run([a]){if(!a)throw new Error('Usage: tent <A|B|D|C|out>');if(a.toLowerCase()==='out'){if(!inTent())return'Not in a tent.';exitTent();return'Stepped outside.'}
    const ti=TENTS.findIndex(t=>t.name[0].toLowerCase()===a[0].toLowerCase());if(ti<0)throw new Error('No such tent. Try A, B, D or C.');
    if(inTent())exitTent();enterTent(ti);return`Inside ${TENTS[ti].name}.`}});

/* detector */
let beepT=0,sig=0;
function updateDetector(dt){
  if(!S.up.detector||!S.detOn||!S.started){sig=0;return}
  let best=0;
  for(const it of items){if(it.found)continue;const range=LOOT[it.type].key?9:7;const d=Math.hypot(it.x-P.x,it.z-P.z);if(d<range){const s=1-d/range;if(s>best)best=s}}
  sig=best;beepT-=dt;
  if(sig>0.02&&beepT<=0){sfx.beep(sig);beepT=lerp(1.1,0.07,sig*sig)}
}

